<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
import ThreeScene from '../../components/ThreeScene.vue'

type ItemSummary={id:string;title:string;category:string;location:string;occurred_at:string;business_status?:string}
type Comparison={
  run_id:number;rank:number;final_score:string;coverage:string;config_version:string;index_version:string
  weights:Record<string,number>;factors:{scores:Record<string,number|null>;effective_weights:Record<string,number>;contributions:Record<string,number>}
  explanation:{level:string;conflicts:string[];missing_factors:string[];text_terms:{term:string;contribution:number}[]}
  source:ItemSummary;candidate:ItemSummary
}
const route=useRoute();const comparison=ref<Comparison|null>(null);const loading=ref(true);const error=ref('');const selected=ref('')
const factorMeta=[['text','文本相似'],['category','类别'],['location','地点'],['time','时间'],['color','颜色'],['brand','品牌']] as const
const factors=computed(()=>factorMeta.map(([key,name])=>({key,name,score:comparison.value?.factors.scores[key]??null})))
const score=computed(()=>Number(comparison.value?.final_score??0))
const sceneNodes=computed(()=>comparison.value?[{label:`${comparison.value.candidate.title} · ${(score.value*100).toFixed(1)} 分`,score:score.value}]:[])
async function load(){try{const params=new URLSearchParams({lost_id:String(route.params.lostId),found_id:String(route.params.foundId)});const response=await api<{data:Comparison}>(`/matches/compare/?${params}`);comparison.value=response.data;selected.value=`${response.data.candidate.title} · ${response.data.explanation.level}`}catch(reason){error.value=reason instanceof ApiError?reason.message:'无法读取匹配结果'}finally{loading.value=false}}
onMounted(load)
</script>

<template><div class="page compare-page"><header><h1 class="page-title">双物品证据对比</h1></header><p v-if="loading" class="state">正在读取匹配结果…</p><div v-else-if="error" class="state error"><AppIcon name="shield"/><h2>无法展示该对比</h2><p>{{error}}</p><RouterLink class="button button-ghost" to="/matches">返回智能匹配</RouterLink></div><template v-else-if="comparison"><section class="pair-strip"><RouterLink :to="`/items/${comparison.source.id}`"><span>遗失信息</span><strong>{{comparison.source.title}}</strong><small>{{comparison.source.category}} · {{comparison.source.location}}</small></RouterLink><div><strong>{{(score*100).toFixed(1)}}</strong><span>线索相似分</span></div><RouterLink :to="`/items/${comparison.candidate.id}`"><span>招领候选 #{{comparison.rank}}</span><strong>{{comparison.candidate.title}}</strong><small>{{comparison.candidate.category}} · {{comparison.candidate.location}}</small></RouterLink></section><div class="compare-layout"><ThreeScene mode="match" label="线索关系" :match-source-label="`我的遗失：${comparison.source.title}`" :match-candidates="sceneNodes" :fallback-items="sceneNodes.map(entry=>entry.label)" @select="selected=$event"/><aside class="panel factor-panel"><span class="status-tag">{{comparison.explanation.level}}</span><h2>{{selected}}</h2><div v-for="factor in factors" :key="factor.key" class="factor"><div><span>{{factor.name}}</span><strong>{{factor.score===null?'未提供':`${(factor.score*100).toFixed(0)}`}}</strong></div><div class="bar"><span :style="{width:`${(factor.score??0)*100}%`}"></span></div></div><div class="coverage"><AppIcon name="shield"/><div><strong>证据覆盖度 {{Number(comparison.coverage).toFixed(2)}}</strong></div></div><div v-if="comparison.explanation.conflicts.length" class="conflicts"><strong>已知冲突</strong><span>{{comparison.explanation.conflicts.join('、')}}</span></div><div v-if="comparison.explanation.text_terms.length" class="terms"><strong>主要共同词项</strong><span v-for="entry in comparison.explanation.text_terms" :key="entry.term">{{entry.term}}</span></div></aside></div></template></div></template>

<style scoped>.pair-strip{display:grid;grid-template-columns:1fr auto 1fr;gap:1px;margin-top:30px;border:1px solid var(--ct-border);border-radius:15px;background:var(--ct-border);overflow:hidden}.pair-strip>a,.pair-strip>div{display:grid;gap:5px;padding:18px;background:var(--ct-surface)}.pair-strip>a:last-child{text-align:right}.pair-strip span,.pair-strip small{color:var(--ct-text-muted);font-size:11px}.pair-strip>div{place-items:center;min-width:150px}.pair-strip>div strong{color:var(--ct-brand);font-size:28px}.compare-layout{display:grid;grid-template-columns:1fr 390px;gap:18px;margin-top:18px}.factor-panel{padding:24px;box-shadow:none}.factor-panel h2{margin:19px 0 8px;font-size:20px}.factor-panel>p{color:var(--ct-text-muted);font-size:13px;line-height:1.65}.factor{margin-top:15px}.factor>div:first-child{display:grid;grid-template-columns:1fr auto;gap:2px 12px}.factor small{grid-row:2;color:var(--ct-text-muted)}.factor strong{grid-row:1/3;grid-column:2;align-self:center;color:var(--ct-brand);font-size:21px}.bar{height:5px;margin-top:8px;overflow:hidden;background:var(--ct-bg);border-radius:5px}.bar span{display:block;height:100%;background:linear-gradient(90deg,var(--ct-info),var(--ct-brand))}.coverage{display:flex;gap:12px;margin-top:22px;padding:14px;color:var(--ct-success);border:1px solid rgba(54,100,75,.25);border-radius:12px;background:rgba(54,100,75,.06)}.coverage span{display:block;margin-top:3px;color:var(--ct-text-muted);font-size:10px}.conflicts,.terms{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px;padding:12px;border:1px solid var(--ct-border);border-radius:10px}.conflicts strong,.terms strong{width:100%;font-size:11px}.conflicts span{color:var(--ct-danger);font-size:11px}.terms span{padding:4px 7px;color:var(--ct-info);background:rgba(40,92,75,.08);border-radius:6px;font-size:10px}.state{display:grid;place-items:center;align-content:center;min-height:430px;color:var(--ct-text-muted);text-align:center}.state>svg{font-size:40px}.error{color:var(--ct-danger)}@media(max-width:920px){.compare-layout{grid-template-columns:1fr}}@media(max-width:650px){.pair-strip{grid-template-columns:1fr}.pair-strip>a:last-child{text-align:left}}</style>
